// 질문지 입력 전체 검증. 엔진은 입력 스키마를 강제하지 않으므로 이 파일이
// 유일한 검사다. 첫 위반 하나를 `QUESTION_FORM_INVALID <칸>: <사유>` 로 돌려준다.

import {
  HANDMADE_OTHER_LABELS,
  HEADER_MAX,
  ID_RE,
  LINE_CONTROL_REASON,
  PROSE_CONTROL_REASON,
  RECOMMEND_ARROW,
  RESERVED_LABELS,
  RESERVED_PREFIXES,
  TITLE_MAX,
  TOTAL_MAX,
  invalidResult,
} from './spec'
import type { FormInput } from './spec'

const isObj = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v)
const isStr = (v: unknown): v is string => typeof v === 'string'
const codePoints = (s: string) => [...s].length

// 입력 안 모든 문자열의 글자 수 합.
export function totalChars(v: unknown): number {
  if (isStr(v)) return codePoints(v)
  if (Array.isArray(v)) return v.reduce((n: number, x) => n + totalChars(x), 0)
  if (isObj(v)) return Object.values(v).reduce((n: number, x) => n + totalChars(x), 0)
  return 0
}

// 한 줄로 그려지는 칸(제목·머리말·묶음·안내글·라벨)은 C0·DEL·C1 전부를, 여러 줄로
// 감기는 칸(안내 문단·질문 문장·설명·선택지 설명·미리보기)은 엔진이 받는 줄바꿈·탭·CR 을
// 뺀 나머지를 금한다. 뒤쪽 집합이 곧 엔진이 패널 전체를 거부하는 문자다.
const LINE_CONTROL_RE = /[\u0000-\u001f\u007f-\u009f]/
const PROSE_CONTROL_RE = /[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f-\u009f]/

// 엔진이 거부하는 문자를 품은 칸이 하나라도 있는가. 보관에서 되살릴 기록은 이 검사가
// 생기기 전에 열렸을 수 있으므로 되살리기 전에 다시 건다. 한 줄 칸의 줄바꿈·탭은 엔진이
// 그리므로 여기서는 걸지 않는다.
export function holdsRefusedControl(form: FormInput): boolean {
  const refused = (s: string | undefined) => s !== undefined && PROSE_CONTROL_RE.test(s)
  if (refused(form.title) || refused(form.intro)) return true
  return form.questions.some(
    q =>
      refused(q.header) ||
      refused(q.question) ||
      refused(q.group) ||
      refused(q.detail) ||
      refused(q.placeholder) ||
      (q.options ?? []).some(o => refused(o.label) || refused(o.description) || refused(o.preview)),
  )
}

function labelProblem(label: string): string | undefined {
  if (label.includes(RECOMMEND_ARROW.trim())) return '라벨에 「←」를 넣지 않습니다. 추천은 recommended 로 표시합니다'
  if (HANDMADE_OTHER_LABELS.includes(label.trim())) return `「${label.trim()}」 라벨은 만들지 않습니다. allowOther 가 기타 입력을 그립니다`
  if (RESERVED_LABELS.includes(label.trim())) return `「${label.trim()}」는 예약 라벨입니다`
  for (const p of RESERVED_PREFIXES) if (label.trim().startsWith(p)) return `「${p}」로 시작하는 라벨은 예약돼 있습니다`
  return undefined
}

// openId: 지금 열린(제출·취소되지 않은) 질문지 id. 없으면 undefined.
export function validateForm(input: unknown, openId: string | undefined): string | undefined {
  const bad = invalidResult
  if (!isObj(input)) return bad('input', '객체가 아닙니다')
  if (!isStr(input.title) || input.title.trim() === '') return bad('title', '필수입니다')
  if (codePoints(input.title) > TITLE_MAX) return bad('title', `${TITLE_MAX}자를 넘습니다`)
  if (LINE_CONTROL_RE.test(input.title)) return bad('title', LINE_CONTROL_REASON)
  if (input.intro !== undefined && !isStr(input.intro)) return bad('intro', '문자열이 아닙니다')
  if (input.intro !== undefined && PROSE_CONTROL_RE.test(input.intro)) return bad('intro', PROSE_CONTROL_REASON)
  if (input.replaces !== undefined) {
    if (!isStr(input.replaces)) return bad('replaces', '문자열이 아닙니다')
    if (input.replaces !== openId) return bad('replaces', openId ? `열린 질문지 id 는 ${openId} 입니다` : '열린 질문지가 없습니다')
  }
  if (!Array.isArray(input.questions) || input.questions.length === 0) return bad('questions', '1개 이상이어야 합니다')

  const seen = new Map<string, { index: number; kind: string; labels: string[] }>()
  for (let i = 0; i < input.questions.length; i++) {
    const q = input.questions[i]
    const at = `questions[${i}]`
    if (!isObj(q)) return bad(at, '객체가 아닙니다')
    if (!isStr(q.id) || !ID_RE.test(q.id)) return bad(`${at}.id`, '^[a-z0-9][a-z0-9_-]{0,31}$ 에 맞지 않습니다')
    if (seen.has(q.id)) return bad(`${at}.id`, `「${q.id}」가 겹칩니다`)
    if (!isStr(q.header) || q.header.trim() === '') return bad(`${at}.header`, '필수입니다')
    if (codePoints(q.header.normalize('NFC')) > HEADER_MAX) return bad(`${at}.header`, `NFC 기준 ${HEADER_MAX} 코드포인트를 넘습니다`)
    if (LINE_CONTROL_RE.test(q.header)) return bad(`${at}.header`, LINE_CONTROL_REASON)
    if (!isStr(q.question) || q.question.trim() === '') return bad(`${at}.question`, '필수입니다')
    if (PROSE_CONTROL_RE.test(q.question)) return bad(`${at}.question`, PROSE_CONTROL_REASON)
    for (const k of ['group', 'detail', 'placeholder'] as const) {
      const v = q[k]
      if (v === undefined) continue
      if (!isStr(v)) return bad(`${at}.${k}`, '문자열이 아닙니다')
      const prose = k === 'detail'
      if ((prose ? PROSE_CONTROL_RE : LINE_CONTROL_RE).test(v)) return bad(`${at}.${k}`, prose ? PROSE_CONTROL_REASON : LINE_CONTROL_REASON)
    }
    for (const k of ['allowOther', 'allowNote'] as const) {
      if (q[k] !== undefined && typeof q[k] !== 'boolean') return bad(`${at}.${k}`, '참·거짓 값이 아닙니다')
    }
    if (q.kind !== 'single' && q.kind !== 'multi' && q.kind !== 'text') return bad(`${at}.kind`, 'single · multi · text 가운데 하나여야 합니다')

    const labels: string[] = []
    if (q.kind === 'text') {
      if (q.options !== undefined && (!Array.isArray(q.options) || q.options.length > 0)) return bad(`${at}.options`, 'text 질문에는 선택지를 두지 않습니다')
    } else {
      if (!Array.isArray(q.options) || q.options.length < 2) return bad(`${at}.options`, `${q.kind} 질문은 선택지가 2개 이상이어야 합니다`)
      let recommended = 0
      for (let j = 0; j < q.options.length; j++) {
        const o = q.options[j]
        const oat = `${at}.options[${j}]`
        if (!isObj(o)) return bad(oat, '객체가 아닙니다')
        if (!isStr(o.label) || o.label.trim() === '') return bad(`${oat}.label`, '필수입니다')
        if (LINE_CONTROL_RE.test(o.label)) return bad(`${oat}.label`, LINE_CONTROL_REASON)
        if (!isStr(o.description)) return bad(`${oat}.description`, '필수입니다')
        if (PROSE_CONTROL_RE.test(o.description)) return bad(`${oat}.description`, PROSE_CONTROL_REASON)
        if (o.preview !== undefined && !isStr(o.preview)) return bad(`${oat}.preview`, '문자열이 아닙니다')
        if (isStr(o.preview) && PROSE_CONTROL_RE.test(o.preview)) return bad(`${oat}.preview`, PROSE_CONTROL_REASON)
        const problem = labelProblem(o.label)
        if (problem) return bad(`${oat}.label`, problem)
        if (labels.includes(o.label)) return bad(`${oat}.label`, `「${o.label}」가 겹칩니다`)
        labels.push(o.label)
        if (o.recommended !== undefined) {
          if (o.recommended !== '추천' && o.recommended !== '에이전트 추천') return bad(`${oat}.recommended`, '「추천」이나 「에이전트 추천」이어야 합니다')
          recommended++
        }
      }
      if (q.kind === 'single' && recommended > 1) return bad(`${at}.options`, 'single 질문에 추천이 둘 이상입니다')
    }

    if (q.when !== undefined) {
      const w = q.when
      if (!isObj(w) || !isStr(w.id) || !Array.isArray(w.selected) || w.selected.length === 0 || !w.selected.every(isStr)) {
        return bad(`${at}.when`, '{id, selected[]} 모양이어야 합니다')
      }
      const target = seen.get(w.id)
      if (!target) return bad(`${at}.when`, `「${w.id}」는 앞쪽 질문이 아닙니다`)
      if (target.kind === 'text') return bad(`${at}.when`, `「${w.id}」는 single·multi 질문이 아닙니다`)
      const missing = (w.selected as string[]).find(s => !target.labels.includes(s))
      if (missing !== undefined) return bad(`${at}.when`, `「${w.id}」에 「${missing}」 라벨이 없습니다`)
    }
    seen.set(q.id, { index: i, kind: q.kind, labels })
  }

  if (totalChars(input) > TOTAL_MAX) return bad('input', `글자 총량이 ${TOTAL_MAX}자를 넘습니다`)
  return undefined
}

// 검증을 통과한 입력에 기본값을 채운다.
export function normalizeForm(input: FormInput): FormInput {
  return {
    ...input,
    questions: input.questions.map(q => ({
      ...q,
      options: q.kind === 'text' ? [] : q.options ?? [],
      allowOther: q.allowOther ?? true,
      allowNote: q.allowNote ?? true,
    })),
  }
}

files.types/index.d.ts:
// 런 상태 패널 mod(hooks/autopilot-status.tsx)와 질문지 서브 mod(hooks/question-form/)가
// $.state 에 두는 값의 계약.

/** 한 줄 안의 색조 조각. 색조는 헬퍼가 정하고 mod 는 그리기만 한다. */
export type PanePart = { tone: string; bold: boolean; text: string }

/**
 * 헬퍼 본문 한 줄: 묶음 id, 감을지(`wrap`) 끝을 자를지(`cut`), 그리고 조각들.
 * 줄 하나는 한 번 감기거나 한 번 잘린다.
 */
export type PaneLine = { bundle: string; wrap: boolean; parts: PanePart[] }

/** 패널이 그리는 것: 마지막으로 성공한 헬퍼 실행의 본문과, 그 뒤 실패를 알리는 경고 줄. */
export type PaneLines = { lines: PaneLine[]; warning: string | null }

/** 자동 열기·닫힘 기록과 갱신 주기 판단에 쓰는 값. 모듈이 다시 적재되어도 남아야 한다. */
export type PaneControl = {
  /** 묻지 않고 패널을 연 런 id. 런마다 한 번만 연다. */
  autoOpenedFor: string[]
  /** 사람이 패널을 닫은 런 id. 이 런으로는 다시 저절로 열지 않는다. */
  dismissedFor: string[]
  /** 마지막 헬퍼 실행을 시작하기 전에 읽은 시각(ms). 실행한 적 없으면 null. */
  lastRunAt: number | null
  /** 마지막으로 본 세션 목록 mtime. 목록이 없으면 null. */
  lastMtime: number | null
  /** 마지막 헬퍼 실행에 넘긴 세션 id. */
  lastSid: string | null
  /** 마지막 좋은 머리 행의 런 id. 런이 없으면 null. */
  rid: string | null
  /** 마지막 좋은 머리 행의 세션 목록 절대 경로. 없으면 null. */
  indexPath: string | null
  /** 마지막 좋은 머리 행의 갱신 주기(ms). */
  refreshMs: number
}

/** 질문지 선택지. 추천 표시는 라벨이 아니라 recommended 로만 한다. */
export type FormOption = {
  label: string
  description: string
  preview?: string
  recommended?: '추천' | '에이전트 추천'
}

/** 질문지 질문 하나. when 은 앞쪽 single·multi 질문의 라벨에 건다. */
export type FormQuestion = {
  id: string
  header: string
  group?: string
  question: string
  detail?: string
  kind: 'single' | 'multi' | 'text'
  options?: FormOption[]
  allowOther?: boolean
  allowNote?: boolean
  placeholder?: string
  when?: { id: string; selected: string[] }
}

/** 질문지 도구의 입력. */
export type FormInput = {
  title: string
  intro?: string
  replaces?: string
  questions: FormQuestion[]
}

/** 쓰던 답. selected 는 라벨 원문(추천 접미 없음), other 는 기타 입력이나 text 질문의 답. */
export type Draft = { selected: string[]; other: string; note: string }
export type Drafts = Record<string, Draft>

export type FormPhase = 'open' | 'submitted' | 'cancelled'

/**
 * 열려 있는 입력칸 하나: 어느 질문의 어느 칸인지, 열 때마다 하나씩 오르는 세대(입력칸 key 에
 * 들어간다), 연 순간의 글(그려지는 value 로 고정된다).
 */
export type FormEditor = { id: string; field: 'other' | 'note'; gen: number; seed: string }

/** 질문지 기록 하나. 제출·취소된 기록은 묶음을 낸 자리에서 버려지므로 열린 것만 남는다. */
export type FormRecord = {
  id: string
  toolUseId: string
  form: FormInput
  drafts: Drafts
  phase: FormPhase
  /** 사람이 닫기 표시를 눌렀거나 열 때 배치되지 않아 패널 대신 상태 줄을 보이는 중. */
  hidden: boolean
  /** 펼쳐 보이는 질문의 id. 나머지 질문은 한 줄로 접힌다. */
  cursor: string
  /** 열려 있는 「기타」·「메모」 입력칸. 없으면 null. */
  editor: FormEditor | null
  /** 이 기록에서 입력칸을 연 횟수. 입력칸 key 의 세대이며, 칸을 닫아도 되돌지 않는다. */
  editorGen: number
  sessionId: string
  savedAt: number
}

/** 질문지가 읽는 사람 프롬프트의 출처 낱말(composer·bridge 등). 모르면 null. */
export type PromptOriginKind = string | null

declare module 'claude-code' {
  interface PluginState {
    'cc-cmds': {
      paneLines: PaneLines
      paneControl: PaneControl
      /** 지금 열린 질문지 기록. 없으면 null. */
      'questionForm.record': FormRecord | null
      /** 마지막 사람 프롬프트의 출처. bridge 이면 질문지를 쓸 수 없다. */
      'questionForm.lastPersonOrigin': PromptOriginKind
      /** 질문지 패널에서 포커스를 받은 요소의 key. 엔진 자신의 정지점이면 null. */
      'questionForm.focusedElement': string | null
    }
  }
}
